import math, struct, zlib, sys
def box(px,py,cx,cy,hx,hy,r):
    qx=abs(px-cx)-hx+r; qy=abs(py-cy)-hy+r
    return math.hypot(max(qx,0),max(qy,0))+min(max(qx,qy),0)-r
def seg(px,py,ax,ay,bx,by):
    vx,vy=bx-ax,by-ay; wx,wy=px-ax,py-ay
    t=max(0,min(1,(wx*vx+wy*vy)/(vx*vx+vy*vy)))
    return math.hypot(wx-vx*t,wy-vy*t)
A=(255,138,61); B=(255,95,109); D=(11,13,18)
def bgc(x,y):
    t=(x+y)/2; return tuple(A[i]+(B[i]-A[i])*t for i in range(3))
def sample(x,y):
    if box(x,y,.5,.5,.5,.5,.22)>0: return None
    c=bgc(x,y)
    if abs(box(x,y,.42,.41,.19,.23,.06))<.03: c=D
    f=box(x,y,.58,.59,.19,.23,.06)
    if f<.045: c=bgc(x,y)
    if f<0:
        c=D
        t=.028
        if (seg(x,y,.58,.47,.58,.68)<t or seg(x,y,.495,.605,.58,.69)<t or seg(x,y,.665,.605,.58,.69)<t): c=A
    return c
def render(n,ss=6):
    rows=[]
    for j in range(n):
        row=bytearray([0])
        for i in range(n):
            acc=[0,0,0]; k=0
            for sj in range(ss):
                for si in range(ss):
                    c=sample((i+(si+.5)/ss)/n,(j+(sj+.5)/ss)/n)
                    if c: k+=1; acc=[acc[q]+c[q] for q in range(3)]
            if k: row+=bytes([round(acc[0]/k),round(acc[1]/k),round(acc[2]/k),round(255*k/ss/ss)])
            else: row+=bytes(4)
        rows.append(bytes(row))
    raw=b''.join(rows)
    def chunk(t,d): return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
    return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',n,n,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(raw,9))+chunk(b'IEND',b'')
out=sys.argv[1]
for n in (16,32,48,128):
    open(f'{out}/icon{n}.png','wb').write(render(n, 8 if n<=32 else 4))
print('ok')
EOF
